<script setup lang="ts">import type {Run} from '../types/domain';import StatusBadge from './common/StatusBadge.vue';import {number,date} from '../utils/format';defineProps<{runs:Run[]}>();</script><template><div class="table-wrap"><table><thead><tr><th>研究与范围</th><th>状态</th><th>当前版本 / λ</th><th>偏差 / 百分点</th><th>建立时间</th><th></th></tr></thead><tbody><tr v-for="r in runs" :key="r.id"><td><b>{{r.name}}</b><small>X {{r.range_low}}—{{r.range_high}}% · {{r.bootstrap_count}}次bootstrap</small></td><td><StatusBadge :status="r.status"/><small v-if="r.pending_batch_id" class="pending-tag">批次 #{{r.pending_batch_id }} 重算中</small></td><td>v{{r.active_version_no||1}} · λ={{r.lambda_ratio}}</td><td>{{number(r.result.bias,3)}}</td><td>{{date(r.created_at)}}</td><td><RouterLink :to="'/results?run='+r.id">读取比对簿 ↗</RouterLink></td></tr></tbody></table></div></template>
